@@ -8,24 +8,30 @@ export function validarNit(nit) {
 }

 // RF-002: el IVA va incluido en el precio; se informa, no se suma.
-export function calcularFactura(items) {
+// RF-006: descuento global opcional, en centavos enteros, restado del total de líneas antes del IVA.
+export function calcularFactura(items, { descuentoGlobal = 0 } = {}) {
   if (!Array.isArray(items) || items.length === 0) throw new Error("Una factura necesita al menos una línea");
-  let totalCentavos = 0;
+  let subtotalCentavos = 0;
   for (const item of items) {
     if (!Number.isInteger(item.cantidad) || item.cantidad <= 0) throw new RangeError("Cantidad inválida");
     if (!Number.isInteger(item.precioUnitarioCentavos) || item.precioUnitarioCentavos < 0)
       throw new RangeError("Precio inválido: debe estar en centavos enteros");
-    totalCentavos += item.cantidad * item.precioUnitarioCentavos;
+    subtotalCentavos += item.cantidad * item.precioUnitarioCentavos;
   }
+  if (!Number.isInteger(descuentoGlobal) || descuentoGlobal < 0)
+    throw new RangeError("Descuento global inválido: debe ser un monto en centavos enteros, no negativo");
+  if (descuentoGlobal > subtotalCentavos) throw new RangeError("El descuento global supera el total de las líneas");
+  const totalCentavos = subtotalCentavos - descuentoGlobal;
   const ivaCentavos = Math.round(totalCentavos * TASA_IVA);
-  return { totalCentavos, ivaCentavos, netoCentavos: totalCentavos - ivaCentavos };
+  const resultado = { totalCentavos, ivaCentavos, netoCentavos: totalCentavos - ivaCentavos };
+  return descuentoGlobal > 0 ? { ...resultado, descuentoGlobalCentavos: descuentoGlobal } : resultado;
 }

 // RF-001, RF-003: emite una factura válida y congelada.
-export function emitirFactura({ numero, nit, razonSocial, items }) {
+export function emitirFactura({ numero, nit, razonSocial, items, descuentoGlobal }) {
   if (!validarNit(nit)) throw new Error("NIT inválido");
   const lineas = Object.freeze(items.map((item) => Object.freeze({ ...item })));
-  return Object.freeze({ numero, nit, razonSocial, items: lineas, ...calcularFactura(items), estado: "emitida" });
+  return Object.freeze({ numero, nit, razonSocial, items: lineas, ...calcularFactura(items, { descuentoGlobal }), estado: "emitida" });
 }

 // Formato para personas: 1.234,50 Bs (lección L-001 del brain de empresa).
diff --git a/tests/factura.test.mjs b/tests/factura.test.mjs
index fabcb45..c1e77a4 100644
--- a/tests/factura.test.mjs
+++ b/tests/factura.test.mjs
@@ -30,6 +30,49 @@ test("RF-003: una factura emitida no se puede modificar", () => {
   assert.throws(() => { "use strict"; f.totalCentavos = 1; }, TypeError);
 });

+const lineasDescuento = [
+  { cantidad: 2, precioUnitarioCentavos: 5000 },
+  { cantidad: 1, precioUnitarioCentavos: 1050 },
+];
+
+test("RF-006-a: el descuento global se resta del total antes del IVA", () => {
+  assert.deepEqual(calcularFactura(lineasDescuento, { descuentoGlobal: 1050 }), {
+    totalCentavos: 10000, ivaCentavos: 1300, netoCentavos: 8700, descuentoGlobalCentavos: 1050,
+  });
+});
+
+test("RF-006-b: sin descuento global el resultado es el de RF-002", () => {
+  const esperado = { totalCentavos: 11050, ivaCentavos: 1437, netoCentavos: 9613, descuentoGlobalCentavos: 0 };
+  assert.deepEqual(calcularFactura(lineasDescuento), esperado);
+  assert.deepEqual(calcularFactura(lineasDescuento, { descuentoGlobal: 0 }), esperado);
+});
+
+test("RF-006-c: descuento con decimales se rechaza (ADR-001)", () => {
+  assert.throws(() => calcularFactura(lineasDescuento, { descuentoGlobal: 10.5 }), RangeError);
+});
+
+test("RF-006-d: descuento negativo se rechaza", () => {
+  assert.throws(() => calcularFactura(lineasDescuento, { descuentoGlobal: -1 }), RangeError);
+});
+
+test("RF-006-e: descuento mayor al total de líneas se rechaza", () => {
+  assert.throws(() => calcularFactura(lineasDescuento, { descuentoGlobal: 11051 }), RangeError);
+});
+
+test("RF-006-f: descuento igual al total deja todo en cero", () => {
+  assert.deepEqual(calcularFactura(lineasDescuento, { descuentoGlobal: 11050 }), {
+    totalCentavos: 0, ivaCentavos: 0, netoCentavos: 0, descuentoGlobalCentavos: 11050,
+  });
+});
+
+test("RF-006-g: emitirFactura con descuento global devuelve factura congelada", () => {
+  const f = emitirFactura({ numero: 8, nit: "1023456", razonSocial: "Cliente SA", items: lineasDescuento, descuentoGlobal: 1050 });
+  assert.equal(f.totalCentavos, 10000);
+  assert.equal(f.descuentoGlobalCentavos, 1050);
+  assert.equal(f.estado, "emitida");
+  assert.ok(Object.isFrozen(f));
+});
+
